@extends('layouts.app')@section('title','Manage Users')@section('content')<div class="pagehead"><div><h1>User accounts</h1><p>Manage access, roles, assignments, and account status.</p></div><a class="primary" href="{{route('admin.users.create')}}">Add user</a></div><form class="filters"><input name="search" value="{{request('search')}}" placeholder="Search name, email or phone"><select name="role"><option value="">All roles</option>@foreach(\App\Models\User::ROLES as $r)<option @selected(request('role')===$r) value="{{$r}}">{{ucwords(str_replace('_',' ',$r))}}</option>@endforeach</select><select name="status"><option value="">All statuses</option><option value="1" @selected(request('status')==='1')>Active</option><option value="0" @selected(request('status')==='0')>Inactive</option></select><button>Filter</button></form><div class="table"><table><thead><tr><th>User</th><th>Role</th><th>Assignment</th><th>Status</th><th>Actions</th></tr></thead><tbody>@forelse($users as $u)<tr><td><b>{{$u->name}}</b><small>{{$u->email}} · {{$u->phone}}</small></td><td>{{ucwords(str_replace('_',' ',$u->role))}}</td><td>{{$u->subject?:'—'}} {{$u->grade?'· '.$u->grade:''}}</td><td><span class="badge {{$u->is_active?'on':'off'}}">{{$u->is_active?'Active':'Inactive'}}</span></td><td class="actions"><a href="{{route('admin.users.edit',$u)}}">Edit</a><form method="POST" action="{{route('admin.users.toggle',$u)}}">@csrf @method('PATCH')<button>{{$u->is_active?'Deactivate':'Activate'}}</button></form><form data-confirm="Delete this user permanently?" method="POST" action="{{route('admin.users.destroy',$u)}}">@csrf @method('DELETE')<button class="danger">Delete</button></form></td></tr>@empty<tr><td colspan="5" class="empty">No users match the selected filters.</td></tr>@endforelse</tbody></table></div>{{$users->links()}}@endsection
